          "title": {
            "en": "The value of remembrance",
            "pa": "ਸਿਮਰਨ ਦਾ ਮੁੱਲ"
          },
          "explanation": {
            "en": "The pauri gathers familiar religious aims—powers, treasures, knowledge, worship and pilgrimage—under remembrance of the One. Its movement is towards goodness, a fruitful life and the Divine’s own grace. The named powers and treasures are part of a traditional spiritual vocabulary, not a programme for acquiring supernatural abilities or money. Notice the final change of posture: after praising remembrance, the speaker bows to those whom God enables to remember. The pauri therefore checks the very pride that spiritual achievement might produce.",
            "pa": "ਪਉੜੀ ਧਾਰਮਿਕ ਜੀਵਨ ਦੇ ਜਾਣੇ ਮਕਸਦਾਂ—ਸ਼ਕਤੀਆਂ, ਨਿਧੀਆਂ, ਗਿਆਨ, ਪੂਜਾ ਅਤੇ ਤੀਰਥ—ਨੂੰ ਇੱਕ ਦੀ ਯਾਦ ਹੇਠ ਇਕੱਠਾ ਕਰਦੀ ਹੈ। ਇਸ ਦੀ ਚਾਲ ਭਲਾਈ, ਸਫਲ ਜੀਵਨ ਅਤੇ ਪ੍ਰਭੂ ਦੀ ਆਪਣੀ ਮਿਹਰ ਵੱਲ ਹੈ। ਰਿੱਧੀਆਂ-ਸਿੱਧੀਆਂ ਅਤੇ ਨਿਧੀਆਂ ਪਰੰਪਰਾਗਤ ਧਾਰਮਿਕ ਸ਼ਬਦ ਹਨ; ਇੱਥੇ ਅਲੌਕਿਕ ਤਾਕਤਾਂ ਜਾਂ ਪੈਸਾ ਪ੍ਰਾਪਤ ਕਰਨ ਦਾ ਕਾਰਜਕ੍ਰਮ ਨਹੀਂ। ਅੰਤਲੀ ਨਿਮਰਤਾ ਵੇਖੋ: ਸਿਮਰਨ ਦੀ ਵਡਿਆਈ ਪਿੱਛੋਂ ਬੋਲਣ ਵਾਲਾ ਉਨ੍ਹਾਂ ਅੱਗੇ ਝੁਕਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਨੂੰ ਪ੍ਰਭੂ ਸਿਮਰਨ ਬਖ਼ਸ਼ਦਾ ਹੈ। ਇਸ ਨਾਲ ਆਤਮਕ ਪ੍ਰਾਪਤੀ ਦਾ ਮਾਣ ਵੀ ਰੋਕਿਆ ਜਾਂਦਾ ਹੈ।"
          },
