          "title": {
            "en": "From craving to clarity",
            "pa": "ਤ੍ਰਿਸ਼ਨਾ ਤੋਂ ਸੂਝ ਵੱਲ"
          },
          "explanation": {
            "en": "The inner sequence is clear: craving quiets, understanding opens, fear loses its grip and the heart receives Naam. “The mind’s grime” is moral and spiritual language for what distorts awareness; it is not a judgement about a person’s body or worth. The holy person’s speech is filled with Divine remembrance. Yet the speaker does not claim that position as a personal title: the final line asks to be a servant even of the servants. Clarity and humility grow together in this account.",
            "pa": "ਅੰਦਰਲੀ ਲੜੀ ਸਪਸ਼ਟ ਹੈ: ਤ੍ਰਿਸ਼ਨਾ ਸ਼ਾਂਤ ਹੁੰਦੀ ਹੈ, ਸੂਝ ਖੁੱਲ੍ਹਦੀ ਹੈ, ਡਰ ਦੀ ਪਕੜ ਘਟਦੀ ਹੈ ਅਤੇ ਹਿਰਦਾ ਨਾਮ ਨੂੰ ਥਾਂ ਦਿੰਦਾ ਹੈ। ਮਨ ਦੀ ਮੈਲ ਉਸ ਵਿਕਾਰੀ ਹਾਲਤ ਲਈ ਨੈਤਿਕ ਅਤੇ ਆਤਮਕ ਬੋਲੀ ਹੈ ਜੋ ਸੁਰਤ ਵਿਗਾੜਦੀ ਹੈ; ਇਹ ਕਿਸੇ ਦੇ ਸਰੀਰ ਜਾਂ ਮਨੁੱਖੀ ਮੁੱਲ ਦਾ ਫ਼ੈਸਲਾ ਨਹੀਂ। ਸਾਧ ਜਨ ਦੇ ਬੋਲ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਨਾਲ ਭਰੇ ਹਨ। ਫਿਰ ਵੀ ਬੋਲਣ ਵਾਲਾ ਇਸ ਨੂੰ ਆਪਣਾ ਖ਼ਿਤਾਬ ਨਹੀਂ ਬਣਾਉਂਦਾ; ਅੰਤਲੀ ਤੁਕ ਸੇਵਕਾਂ ਦਾ ਵੀ ਸੇਵਕ ਬਣਨ ਦੀ ਨਿਮਰਤਾ ਰੱਖਦੀ ਹੈ। ਇੱਥੇ ਸੂਝ ਅਤੇ ਨਿਮਰਤਾ ਇਕੱਠੀਆਂ ਵਧਦੀਆਂ ਹਨ।"
          },
