          "explanation": {
            "en": "The opening example is deliberately large: even the ruler of the whole world can remain unhappy. Wealth cannot serve as an ultimate barrier, and multiplying pleasures does not quiet thirst. Naam is presented as contentment and a companion on the lonely journey. The critique concerns what possessions cannot finally do; it does not say that food, shelter, fair wages or practical support are unimportant. The ending again names a Guru-oriented way of living, so contentment is not reduced to a mood one forces upon oneself.",
            "pa": "ਸ਼ੁਰੂ ਦੀ ਮਿਸਾਲ ਬਹੁਤ ਵੱਡੀ ਹੈ: ਪੂਰੀ ਦੁਨੀਆ ਦਾ ਰਾਜਾ ਵੀ ਦੁਖੀ ਰਹਿ ਸਕਦਾ ਹੈ। ਧਨ ਅੰਤਿਮ ਬਚਾਅ ਦਾ ਬੰਨ੍ਹ ਨਹੀਂ ਬਣ ਸਕਦਾ ਅਤੇ ਸੁਆਦ ਵਧਾਉਣ ਨਾਲ ਤ੍ਰਿਸ਼ਨਾ ਨਹੀਂ ਮੁੱਕਦੀ। ਨਾਮ ਨੂੰ ਰੱਜ ਅਤੇ ਇਕੱਲੇ ਰਸਤੇ ਦੇ ਸਾਥ ਵਜੋਂ ਰੱਖਿਆ ਹੈ। ਗੱਲ ਵਸਤੂਆਂ ਦੀ ਹੱਦ ਬਾਰੇ ਹੈ; ਰੋਟੀ, ਛੱਤ, ਨਿਆਂਪੂਰਨ ਮਜ਼ਦੂਰੀ ਜਾਂ ਅਮਲੀ ਸਹਾਇਤਾ ਨੂੰ ਬੇਮੁੱਲ ਨਹੀਂ ਕਿਹਾ। ਅੰਤ ਫਿਰ ਗੁਰੂ ਵੱਲ ਰੁਖ ਵਾਲੇ ਜੀਵਨ ਦੀ ਗੱਲ ਕਰਦਾ ਹੈ, ਇਸ ਲਈ ਸੰਤੋਖ ਆਪਣੇ ਉੱਤੇ ਥੋਪਿਆ ਅਹਿਸਾਸ ਨਹੀਂ ਬਣਦਾ।"
          },
          "reflection": {
            "en": "Which need requires practical action, and which repeated desire continues growing even after it is met?",
            "pa": "ਕਿਹੜੀ ਲੋੜ ਲਈ ਅਮਲੀ ਕਦਮ ਜ਼ਰੂਰੀ ਹੈ, ਅਤੇ ਕਿਹੜੀ ਵਾਰ ਵਾਰ ਦੀ ਇੱਛਾ ਪੂਰੀ ਹੋ ਕੇ ਵੀ ਵਧਦੀ ਰਹਿੰਦੀ ਹੈ?"
          },
