          "title": {
            "en": "Effort without the right orientation",
            "pa": "ਸਹੀ ਰੁਖ ਤੋਂ ਬਿਨਾਂ ਜਤਨ"
          },
          "explanation": {
            "en": "The long list builds towards the last two lines: none of the named efforts equals reflection on Naam from a Guru-oriented heart. The dramatic bodily sacrifices are examples being criticised, not practices being prescribed. “Even once” gives weight to the quality of orientation; it should not become a claim that one mechanical utterance guarantees a spiritual result. For the word ratna in the fire-offering line, Professor Sahib Singh reads ghee, while some English renderings read jewels. This draft uses “offerings” in the short meaning and preserves the original word.",
            "pa": "ਲੰਮੀ ਸੂਚੀ ਅੰਤ ਦੀਆਂ ਦੋ ਤੁਕਾਂ ਵੱਲ ਲੈ ਜਾਂਦੀ ਹੈ: ਇਹ ਜਤਨ ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹਿਰਦੇ ਦੀ ਨਾਮ-ਵੀਚਾਰ ਦੇ ਬਰਾਬਰ ਨਹੀਂ। ਕਠਿਨ ਸਰੀਰਕ ਬਲੀਆਂ ਆਲੋਚਨਾ ਲਈ ਦਿੱਤੀਆਂ ਮਿਸਾਲਾਂ ਹਨ, ਕਰਨ ਲਈ ਹਦਾਇਤਾਂ ਨਹੀਂ। ਇਕ ਬਾਰ ਰੁਖ ਦੀ ਸੱਚਾਈ ਨੂੰ ਭਾਰ ਦਿੰਦਾ ਹੈ; ਇਸ ਨੂੰ ਇਕ ਮਸ਼ੀਨੀ ਉਚਾਰਨ ਨਾਲ ਪੱਕਾ ਆਤਮਕ ਨਤੀਜਾ ਮਿਲਣ ਦਾ ਫ਼ਾਰਮੂਲਾ ਨਾ ਬਣਾਓ। ਹਵਨ ਵਾਲੀ ਤੁਕ ਦੇ ਰਤਨਾ ਨੂੰ ਪ੍ਰੋਫੈਸਰ ਸਾਹਿਬ ਸਿੰਘ ਘਿਉ ਲੈਂਦੇ ਹਨ, ਜਦਕਿ ਕੁਝ ਅੰਗਰੇਜ਼ੀ ਅਰਥ ਗਹਿਣੇ ਲੈਂਦੇ ਹਨ। ਛੋਟੇ ਅਰਥ ਵਿੱਚ ਚੜ੍ਹਾਵੇ ਆਖ ਕੇ ਮੂਲ ਸ਼ਬਦ ਜਿਉਂ ਦਾ ਤਿਉਂ ਰੱਖਿਆ ਹੈ।"
          },
