          "status": "draft",
          "title": {
            "en": "Does the practice remove ego?",
            "pa": "ਕੀ ਅਭਿਆਸ ਹਉਮੈ ਘਟਾਉਂਦਾ ਹੈ?"
          },
          "explanation": {
            "en": "Travel, long life, renunciation, generosity and severe bodily disciplines all lead to the same test: does the ego’s stain depart? The pauri says that even extreme exertion can leave it intact. Its references to Jain disciplines belong to this argument about the limits of ascetic achievement; they are not a full description of Jain tradition or a licence to disparage people. In the gift list, haivar is read as fine horses, following Professor Sahib Singh’s lexical gloss. The conclusion turns again to Naam through the Guru, rather than to a harsher technique.",
            "pa": "ਯਾਤਰਾ, ਲੰਮੀ ਉਮਰ, ਤਿਆਗ, ਦਾਨ ਅਤੇ ਕਠਿਨ ਸਰੀਰਕ ਸਾਧਨ ਇੱਕੋ ਪਰਖ ਵੱਲ ਆਉਂਦੇ ਹਨ: ਕੀ ਹਉਮੈ ਦੀ ਮੈਲ ਜਾਂਦੀ ਹੈ? ਪਉੜੀ ਦੱਸਦੀ ਹੈ ਕਿ ਬਹੁਤ ਕਠਿਨ ਜਤਨ ਨਾਲ ਵੀ ਉਹ ਕਾਇਮ ਰਹਿ ਸਕਦੀ ਹੈ। ਜੈਨ ਸੰਜਮਾਂ ਦਾ ਜ਼ਿਕਰ ਤਪੱਸਿਆ ਦੀ ਪ੍ਰਾਪਤੀ ਦੀ ਹੱਦ ਵਾਲੀ ਦਲੀਲ ਵਿੱਚ ਹੈ; ਇਹ ਸਾਰੀ ਜੈਨ ਪਰੰਪਰਾ ਦਾ ਵੇਰਵਾ ਜਾਂ ਲੋਕਾਂ ਨੂੰ ਨੀਵਾਂ ਦਿਖਾਉਣ ਦੀ ਛੂਟ ਨਹੀਂ। ਦਾਨ ਦੀ ਸੂਚੀ ਵਿੱਚ ਹੈਵਰ ਨੂੰ ਪ੍ਰੋਫੈਸਰ ਸਾਹਿਬ ਸਿੰਘ ਦੇ ਸ਼ਬਦ-ਅਰਥ ਅਨੁਸਾਰ ਉੱਤਮ ਘੋੜੇ ਲਿਆ ਹੈ। ਨਤੀਜਾ ਹੋਰ ਕਠਿਨ ਤਕਨੀਕ ਦੀ ਥਾਂ ਮੁੜ ਗੁਰੂ ਰਾਹੀਂ ਨਾਮ ਵੱਲ ਜਾਂਦਾ ਹੈ।"
          },
