        "pa": "ਇਹ ਅਸਟਪਦੀ ਵੱਡੇ ਦਿਸਦੇ ਧਾਰਮਿਕ ਜਤਨਾਂ ਦੀ ਪਰਖ ਕਰ ਕੇ ਵੀ ਅੰਤ ਵਿੱਚ ਸੁੱਚੀ ਕਰਣੀ ਉੱਤੇ ਜ਼ੋਰ ਕਿਉਂ ਦਿੰਦੀ ਹੈ? ਜਵਾਬ ਵਿੱਚ ਦੂਜੀ, ਛੇਵੀਂ ਅਤੇ ਅੱਠਵੀਂ ਪਉੜੀ ਵਰਤੋ।"
