        "en": "The fourth Ashtpadi moves from receiving care to recognising forgetfulness. Life from the womb to old age, family, water, air, and bodily faculties are named as gifts. The middle stanzas expose misplaced priorities and the gap between religious appearance and inner conduct. The speaker then admits the need for help and ends in direct prayer: the Divine is both mother and father. Notice that sharp descriptions of human failure repeatedly end with an appeal to compassion. This is a prayer of self-examination, not a list of people whom the reader is entitled to condemn.",
