          "title": {
            "en": "“Take my hand”: the language of dependence",
            "pa": "“ਹੱਥ ਫੜ ਲੈ”: ਸਹਾਰੇ ਦੀ ਬੋਲੀ"
          },
          "explanation": {
            "en": "The stanza draws on bodily limitations to express the speaker’s spiritual inability and need for help. Its movement is toward relationship: take the hand and stay to the end. These historical images must not be turned into claims that disabled people lack understanding, faith, or access to the Divine. Nor are they accurate universal descriptions of what people with disabilities can do. The central prayer is that grace accomplishes what self-confident effort alone cannot.",
            "pa": "ਪਉੜੀ ਸਰੀਰਕ ਸੀਮਾਵਾਂ ਦੇ ਬਿੰਬਾਂ ਰਾਹੀਂ ਜੀਵ ਦੀ ਆਤਮਕ ਅਸਮਰੱਥਾ ਅਤੇ ਸਹਾਰੇ ਦੀ ਲੋੜ ਦੱਸਦੀ ਹੈ। “ਹੱਥ ਫੜ ਲੈ” ਨਾਲ ਰਿਸ਼ਤਾ ਅਤੇ ਅੰਤ ਤਕ ਸਾਥ ਮੰਗਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਪੁਰਾਣੀ ਕਾਵਿਕ ਬੋਲੀ ਨੂੰ ਅਪਾਹਜ ਵਿਅਕਤੀਆਂ ਦੀ ਸੂਝ, ਸ਼ਰਧਾ ਜਾਂ ਰੱਬ ਤਕ ਪਹੁੰਚ ਘੱਟ ਹੋਣ ਦਾ ਨਿਰਣਾ ਨਹੀਂ ਬਣਾਉਣਾ। ਇਹ ਉਨ੍ਹਾਂ ਦੀਆਂ ਅਸਲ ਸਮਰੱਥਾਵਾਂ ਦਾ ਸਰਬਵਿਆਪੀ ਵੇਰਵਾ ਵੀ ਨਹੀਂ। ਮੂਲ ਭਾਵ ਆਪਣੀ ਸੀਮਾ ਮੰਨ ਕੇ ਕਿਰਪਾ ਦੀ ਬੇਨਤੀ ਹੈ।"
          },
