          "title": {
            "en": "No cleverness can replace relationship",
            "pa": "ਚਤੁਰਾਈ ਦੀ ਥਾਂ ਸੱਚਾ ਸੰਬੰਧ"
          },
          "explanation": {
            "en": "After exposing pretence, the speaker prays to the One who already knows the inner life. Nearness and distance describe how Divine presence is realised, while the same stanza says God pervades all places. The Divine is beyond manipulation by schemes. Grace draws a person into service, and the closing instruction returns to moment-by-moment remembrance. This is not permission to judge who has been permanently rejected or to stop making ethical effort.",
            "pa": "ਵਿਖਾਵਾ ਖੋਲ੍ਹਣ ਮਗਰੋਂ ਜੀਵ ਉਸ ਅੱਗੇ ਬੇਨਤੀ ਕਰਦਾ ਹੈ ਜੋ ਅੰਦਰਲਾ ਜੀਵਨ ਪਹਿਲਾਂ ਹੀ ਜਾਣਦਾ ਹੈ। ਨੇੜਤਾ ਅਤੇ ਦੂਰੀ ਅਨੁਭਵ ਤੇ ਸੂਝ ਦੀ ਬੋਲੀ ਹਨ; ਇਸੇ ਪਉੜੀ ਵਿੱਚ ਪ੍ਰਭੂ ਹਰ ਥਾਂ ਸਮਾਇਆ ਹੈ। ਚਤੁਰ ਜੁਗਤ ਨਾਲ ਉਸ ਨੂੰ ਵੱਸ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ। ਮਿਹਰ ਸੇਵਾ ਵੱਲ ਜੋੜਦੀ ਹੈ ਅਤੇ ਅੰਤ ਪਲ-ਪਲ ਸਿਮਰਨ ਵੱਲ ਮੁੜਦਾ ਹੈ। ਇਸ ਤੋਂ ਕਿਸੇ ਨੂੰ ਸਦਾ ਲਈ ਰੱਦ ਹੋਇਆ ਮੰਨਣਾ ਜਾਂ ਕਰਨੀ ਦਾ ਯਤਨ ਛੱਡਣਾ ਨਹੀਂ ਨਿਕਲਦਾ।"
          },
