            "pa": "ਕੱਪੜੇ, ਆਰਾਮ, ਲੋਕਾਂ ਦਾ ਆਦਰ ਅਤੇ ਧਰਮ ਨਿਭਾਉਣ ਦੀ ਸਮਰੱਥਾ ਇਕੋ ਦਾਤ-ਚੇਤੇ ਦੀ ਲੜੀ ਵਿੱਚ ਹਨ। ਲੋਕ-ਮਾਣ ਨੂੰ ਉੱਚੀ ਆਤਮਕ ਕੀਮਤ ਦਾ ਸਬੂਤ ਨਹੀਂ ਬਣਾਇਆ ਗਿਆ। ਭਾਵ ਇਹ ਮਾਣ ਹਟਾਉਣਾ ਹੈ ਕਿ ਸਾਰੀ ਪਛਾਣ ਮੈਂ ਹੀ ਬਣਾਈ ਹੈ। ਅੰਤ ਲੋਕਾਂ ਦੇ ਆਦਰ ਤੋਂ ਦਰਗਾਹ ਦੇ ਮਾਣ ਵੱਲ ਲੈ ਜਾਂਦਾ ਹੈ, ਜਿੱਥੇ ਦਿਖਾਵੇ ਨਾਲੋਂ ਨਾਮ ਅਤੇ ਸੁਚੱਜੀ ਕਰਨੀ ਦਾ ਮੁੱਲ ਹੈ।"
