            "pa": "ਦੇਹ ਸੋਨੇ ਵਰਗੀ ਅਤੇ ਦੁਰਲੱਭ ਕਹੀ ਗਈ ਹੈ। ਸਿਹਤ ਅਤੇ ਐਬਾਂ ਉੱਤੇ ਮਿਲੀ ਓਟ ਆਪਣਾ ਮਾਣ ਵਧਾਉਣ ਦੀ ਥਾਂ ਸ਼ੁਕਰ ਤੇ ਨਿਮਰਤਾ ਲਿਆਉਂਦੇ ਹਨ। ਇਸ ਤੋਂ ਬਿਮਾਰੀ ਜਾਂ ਅਪਾਹਜਤਾ ਨੂੰ ਮਿਹਰ ਦੀ ਘਾਟ ਨਹੀਂ ਮੰਨਣਾ, ਨਾ ਭਗਤੀ ਨਾਲ ਬਿਮਾਰੀ ਨਾ ਹੋਣ ਦੀ ਗਾਰੰਟੀ ਹੈ। ਐਬ ਢੱਕੇ ਜਾਣ ਦਾ ਬਿੰਬ ਜਵਾਬਦੇਹੀ ਤੋਂ ਬਚਣ ਲਈ ਨੁਕਸਾਨ ਲੁਕਾਉਣ ਦੀ ਛੁੱਟੀ ਵੀ ਨਹੀਂ। ਦਾਤ ਨੂੰ ਸਮਝ ਕੇ ਭਗਤੀ ਨਾਲ ਜੀਉਣਾ ਮਕਸਦ ਹੈ।"
