      "title": {
        "en": "The transforming company of the holy",
        "pa": "ਸਾਧ-ਸੰਗਤ ਨਾਲ ਜੀਵਨ ਦਾ ਬਦਲਾਅ"
      },
      "overview": {
        "en": "Ashtpadi 7 returns again and again to saadh kai sang: in the company of the spiritually realised. Its account moves through clearer understanding, restraint of the passions, humility, freedom from hostility, sharing spiritual wealth, and remembrance of the Divine in everyone. Liberation includes the religious horizon of death and what lies beyond it. The closing declaration of no separation between the holy and the Divine gives this company its deepest meaning. The repeated emphasis is the life shaped by Naam and grace; the passage does not name an individual or offer a hereditary qualification for sainthood.",
        "pa": "ਸੱਤਵੀਂ ਅਸਟਪਦੀ ਵਿੱਚ ਸਾਧ ਕੈ ਸੰਗਿ ਮੁੜ ਮੁੜ ਆਉਂਦਾ ਹੈ: ਪ੍ਰਭੂ ਨਾਲ ਜੁੜੇ ਹੋਏ ਜਨਾਂ ਦੀ ਸੰਗਤ ਵਿੱਚ। ਇਸ ਦੀ ਵਿਚਾਰ-ਚਾਲ ਸੂਝ, ਵਿਕਾਰਾਂ ਉੱਤੇ ਸੰਜਮ, ਨਿਮਰਤਾ, ਵੈਰ ਤੋਂ ਮੁਕਤੀ, ਆਤਮਕ ਧਨ ਦੀ ਵੰਡ ਅਤੇ ਹਰੇਕ ਵਿੱਚ ਪ੍ਰਭੂ ਦੇ ਦਰਸ਼ਨ ਤੱਕ ਜਾਂਦੀ ਹੈ। ਮੁਕਤੀ ਦੇ ਧਾਰਮਿਕ ਭਾਵ ਵਿੱਚ ਮੌਤ ਅਤੇ ਉਸ ਤੋਂ ਅੱਗੇ ਦਾ ਪ੍ਰਸੰਗ ਵੀ ਹੈ। ਅੰਤ ਵਿੱਚ ਸਾਧ ਅਤੇ ਪ੍ਰਭੂ ਵਿਚਕਾਰ ਭੇਦ ਨਾ ਹੋਣ ਦਾ ਬਚਨ ਇਸ ਸੰਗਤ ਦਾ ਡੂੰਘਾ ਆਧਾਰ ਦੱਸਦਾ ਹੈ। ਜ਼ੋਰ ਨਾਮ ਅਤੇ ਕਿਰਪਾ ਨਾਲ ਘੜੇ ਜੀਵਨ ਉੱਤੇ ਹੈ; ਇਸ ਭਾਗ ਵਿੱਚ ਕਿਸੇ ਵਿਅਕਤੀ ਦਾ ਨਾਮ ਜਾਂ ਖ਼ਾਨਦਾਨੀ ਸੰਤ-ਪਦਵੀ ਨਹੀਂ ਦਿੱਤੀ ਗਈ।"
      },
