          "explanation": {
            "en": "The speaker now voices a personal desire to hear Naam and sing Divine qualities. Remembrance becomes sweetness, perception of the Divine in every heart, and willingness to live by the Divine command. The language of all ailments disappearing is broad in the verse and belongs to this account of liberation and transformed life. It should retain that devotional force without becoming a clinical promise about every illness. The final line locates the meeting with the holy in blessed conjunction or grace. The whole sequence joins listening, praise, perception and obedient living.",
            "pa": "ਹੁਣ ਬੋਲਣ ਵਾਲਾ ਨਾਮ ਸੁਣਨ ਅਤੇ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਉਣ ਦੀ ਆਪਣੀ ਲੋਚਾ ਪ੍ਰਗਟ ਕਰਦਾ ਹੈ। ਸਿਮਰਨ ਪ੍ਰਭੂ ਦੀ ਮਿਠਾਸ, ਹਰੇਕ ਹਿਰਦੇ ਵਿੱਚ ਉਸ ਦੇ ਦਰਸ਼ਨ ਅਤੇ ਉਸ ਦੀ ਆਗਿਆ ਅਨੁਸਾਰ ਜੀਊਣ ਨਾਲ ਜੁੜਦਾ ਹੈ। ਸਾਰੇ ਰੋਗ ਮਿਟਣ ਦੀ ਤੁਕ ਦਾ ਭਾਵ ਵਿਸ਼ਾਲ ਹੈ ਅਤੇ ਇਸ ਮੁਕਤੀ ਤੇ ਬਦਲੇ ਜੀਵਨ ਦੇ ਵਰਣਨ ਵਿੱਚ ਆਉਂਦਾ ਹੈ। ਇਸ ਦੀ ਭਗਤੀ-ਭਾਵਨਾ ਕਾਇਮ ਰੱਖਣੀ ਚਾਹੀਦੀ ਹੈ; ਇਸ ਨੂੰ ਹਰ ਬਿਮਾਰੀ ਬਾਰੇ ਡਾਕਟਰੀ ਗਾਰੰਟੀ ਨਹੀਂ ਬਣਾਉਣਾ ਚਾਹੀਦਾ। ਅੰਤਲੀ ਤੁਕ ਸਾਧ ਨਾਲ ਮਿਲਾਪ ਨੂੰ ਸੁਭਾਗੇ ਸੰਜੋਗ ਜਾਂ ਕਿਰਪਾ ਨਾਲ ਜੋੜਦੀ ਹੈ। ਸਾਰੀ ਲੜੀ ਸੁਣਨ, ਗਾਉਣ, ਵੇਖਣ ਅਤੇ ਆਗਿਆ ਮੰਨ ਕੇ ਜੀਊਣ ਨੂੰ ਇਕੱਠਾ ਰੱਖਦੀ ਹੈ।"
          },
