          "status": "draft",
          "title": {
            "en": "Learning that awakens and teaches everyone",
            "pa": "ਉਹ ਵਿਦਿਆ ਜੋ ਜਗਾਉਂਦੀ ਅਤੇ ਸਭ ਨੂੰ ਸਿਖਾਉਂਦੀ ਹੈ"
          },
          "explanation": {
            "en": "The pandit first brings understanding to their own mind and discovers the essence of Naam within. Teaching then gives life to others. The roots of the Vedas, Puranas and Smritis are understood through this realisation, and the manifest is recognised within the subtle. Freedom from returning to birth belongs to the religious promise of the pauri. The teacher offers instruction to all four varnas. The text uses that inherited classification to state the breadth of access; it does not make birth the measure of the teacher’s insight. Knowledge bears fruit in an awakened life and a generous teaching practice.",
            "pa": "ਪੰਡਿਤ ਪਹਿਲਾਂ ਆਪਣੇ ਮਨ ਨੂੰ ਸਮਝਾਉਂਦਾ ਅਤੇ ਅੰਦਰ ਨਾਮ ਦਾ ਸਾਰ ਲੱਭਦਾ ਹੈ। ਫਿਰ ਉਸ ਦੀ ਸਿੱਖਿਆ ਹੋਰਨਾਂ ਨੂੰ ਜੀਵਨ ਦਿੰਦੀ ਹੈ। ਵੇਦਾਂ, ਪੁਰਾਣਾਂ ਅਤੇ ਸਿਮ੍ਰਿਤੀਆਂ ਦਾ ਮੂਲ ਇਸ ਪਛਾਣ ਨਾਲ ਸਮਝਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸੂਖਮ ਵਿੱਚ ਅਸਥੂਲ ਜਾਣਿਆ ਜਾਂਦਾ ਹੈ। ਮੁੜ ਜੂਨ ਵਿੱਚ ਨਾ ਆਉਣਾ ਪਉੜੀ ਦੇ ਧਾਰਮਿਕ ਵਚਨ ਦਾ ਹਿੱਸਾ ਹੈ। ਅਧਿਆਪਕ ਚਾਰਾਂ ਵਰਣਾਂ ਨੂੰ ਉਪਦੇਸ਼ ਦਿੰਦਾ ਹੈ। ਪਾਠ ਪ੍ਰਚਲਿਤ ਵੰਡ ਦਾ ਜ਼ਿਕਰ ਕਰ ਕੇ ਪਹੁੰਚ ਦੀ ਵਿਸ਼ਾਲਤਾ ਦੱਸਦਾ ਹੈ; ਜਨਮ ਨੂੰ ਅਧਿਆਪਕ ਦੀ ਸੂਝ ਦਾ ਮਾਪ ਨਹੀਂ ਬਣਾਉਂਦਾ। ਗਿਆਨ ਜਾਗੇ ਹੋਏ ਜੀਵਨ ਅਤੇ ਖੁੱਲ੍ਹੇ ਦਿਲ ਨਾਲ ਸਿੱਖਿਆ ਵੰਡਣ ਵਿੱਚ ਫਲਦਾ ਹੈ।"
          },
