          "status": "draft",
          "title": {
            "en": "The true servant among all",
            "pa": "ਸਭ ਵਿੱਚ ਰਹਿੰਦਾ ਸੱਚਾ ਸੇਵਕ"
          },
          "explanation": {
            "en": "The person in whose mind the Supreme Divine dwells is called the true Ramdas. The surrounding lines define the expression as servant of the Divine; Professor Sahib Singh confirms this lexical reading. The servant of servants perceives the One within all and knows the Divine to be close. Grace brings understanding, and life continues among everyone with inward freedom from attachment. Udaas here describes that inner relationship to the world. This pauri does not require withdrawal from family or society, nor does its use of Ramdas automatically identify one historical person.",
            "pa": "ਜਿਸ ਮਨੁੱਖ ਦੇ ਮਨ ਵਿੱਚ ਪਾਰਬ੍ਰਹਮ ਵੱਸਦਾ ਹੈ, ਉਸ ਨੂੰ ਸੱਚਾ ਰਾਮਦਾਸ ਕਿਹਾ ਹੈ। ਨੇੜਲੀਆਂ ਤੁਕਾਂ ਇਸ ਸ਼ਬਦ ਦਾ ਭਾਵ ਪ੍ਰਭੂ ਦੇ ਸੇਵਕ ਵਜੋਂ ਖੋਲ੍ਹਦੀਆਂ ਹਨ; ਪ੍ਰੋਫੈਸਰ ਸਾਹਿਬ ਸਿੰਘ ਵੀ ਇਹੀ ਸ਼ਬਦਾਰਥ ਦਿੰਦੇ ਹਨ। ਦਾਸਾਂ ਦਾ ਦਾਸ ਸਭ ਅੰਦਰ ਇੱਕ ਨੂੰ ਵੇਖਦਾ ਅਤੇ ਪ੍ਰਭੂ ਨੂੰ ਨੇੜੇ ਜਾਣਦਾ ਹੈ। ਕਿਰਪਾ ਨਾਲ ਸੋਝੀ ਮਿਲਦੀ ਹੈ ਅਤੇ ਸਭ ਵਿੱਚ ਰਹਿੰਦਿਆਂ ਅੰਦਰ ਮੋਹ ਤੋਂ ਆਜ਼ਾਦੀ ਰਹਿੰਦੀ ਹੈ। ਇੱਥੇ ਉਦਾਸ ਜਗਤ ਨਾਲ ਉਸ ਅੰਦਰਲੇ ਸੰਬੰਧ ਨੂੰ ਦੱਸਦਾ ਹੈ। ਪਉੜੀ ਪਰਿਵਾਰ ਜਾਂ ਸਮਾਜ ਤੋਂ ਲਾਜ਼ਮੀ ਦੂਰ ਜਾਣ ਲਈ ਨਹੀਂ ਕਹਿੰਦੀ ਅਤੇ ਰਾਮਦਾਸ ਸ਼ਬਦ ਆਪਣੇ ਆਪ ਕਿਸੇ ਇੱਕ ਇਤਿਹਾਸਕ ਵਿਅਕਤੀ ਦੀ ਪਛਾਣ ਨਹੀਂ ਬਣਦਾ।"
          },
