        "pa": "ਹਰੇਕ ਧਾਰਮਿਕ ਸ਼ਬਦ ਨੂੰ ਉਸ ਦੀ ਆਪਣੀ ਤੁਕ ਅਤੇ ਪਉੜੀ ਵਿੱਚ ਪੜ੍ਹੋ। ਇੱਥੇ ਅਪਰਸ ਜਾਤ ਦਾ ਨਾਮ ਨਹੀਂ; ਭਗਉਤੀ ਅਤੇ ਰਾਮਦਾਸ ਦਾ ਭਾਵ ਨਾਲ ਦੱਸੇ ਗੁਣਾਂ ਤੋਂ ਖੁੱਲ੍ਹਦਾ ਹੈ। ਚਾਰ ਵਰਣਾਂ ਦਾ ਜ਼ਿਕਰ ਸਭ ਦੀ ਪਹੁੰਚ ਉੱਤੇ ਜ਼ੋਰ ਦਿੰਦਾ ਹੈ, ਖ਼ਾਨਦਾਨੀ ਆਤਮਕ ਵਡਿਆਈ ਉੱਤੇ ਨਹੀਂ। ਨਾਮ ਦੇ ਔਖਧ ਹੋਣ ਅਤੇ ਅੰਮ੍ਰਿਤ-ਵਿਹੁ ਦੀ ਤੁਲਨਾ ਭਗਤੀ ਤੇ ਆਚਰਨ ਦੀ ਸਿੱਖਿਆ ਵਿੱਚ ਹਨ, ਡਾਕਟਰੀ ਹਦਾਇਤ ਨਹੀਂ। ਸਾਰੀਆਂ ਵਿਆਖਿਆਵਾਂ ਅਤੇ ਸਵਾਲ ਸੰਪਾਦਕੀ ਖਰੜੇ ਹਨ ਜਿਨ੍ਹਾਂ ਦੀ ਯੋਗ ਵਿਦਵਾਨ ਵੱਲੋਂ ਸਮੀਖਿਆ ਬਾਕੀ ਹੈ।"
