          "title": {
            "en": "The changing expanse and the enduring One",
            "pa": "ਬਦਲਦਾ ਪਸਾਰਾ ਅਤੇ ਸਦਾ ਕਾਇਮ ਇੱਕ"
          },
          "explanation": {
            "en": "Sources of life, regions, universes, and beings coming into existence belong to a repeatedly unfolding expanse. Against that movement, the line about the one Ekankar establishes continuity: many forms arise and return, while the One remains. The bani does not supply dates, physical mechanisms, or a numerical model of cosmic cycles here. Its point is the dependence of all manifestation on the same inexhaustible source. Even the largest imaginable panorama cannot finish the account of God.",
            "pa": "ਜੀਵਨ ਦੀਆਂ ਖਾਣੀਆਂ, ਖੰਡ, ਬ੍ਰਹਮੰਡ ਅਤੇ ਜਨਮ ਲੈਂਦੇ ਪ੍ਰਾਣੀ ਵਾਰ ਵਾਰ ਪਸਰਦੇ ਪਸਾਰੇ ਵਿੱਚ ਆਉਂਦੇ ਹਨ। ਇਸ ਬਦਲਾਅ ਦੇ ਵਿਚਕਾਰ ਇੱਕ ਏਕੰਕਾਰ ਵਾਲੀ ਪੰਕਤੀ ਨਿਰੰਤਰਤਾ ਦੱਸਦੀ ਹੈ: ਰੂਪ ਉਪਜਦੇ ਅਤੇ ਸਮਾਉਂਦੇ ਹਨ, ਇੱਕ ਕਾਇਮ ਰਹਿੰਦਾ ਹੈ। ਇਥੇ ਬਾਣੀ ਬ੍ਰਹਮੰਡੀ ਚੱਕਰਾਂ ਦੀਆਂ ਤਾਰੀਖਾਂ, ਭੌਤਿਕ ਜੁਗਤੀਆਂ ਜਾਂ ਗਣਿਤ ਦਾ ਨਮੂਨਾ ਨਹੀਂ ਦਿੰਦੀ। ਭਾਵ ਹਰ ਪ੍ਰਗਟ ਰੂਪ ਦੀ ਇੱਕੋ ਬੇਅੰਤ ਮੂਲ ਨਾਲ ਨਿਰਭਰਤਾ ਹੈ। ਸਭ ਤੋਂ ਵੱਡੀ ਕਲਪਨਾ ਵੀ ਪ੍ਰਭੂ ਦਾ ਬਿਆਨ ਪੂਰਾ ਨਹੀਂ ਕਰ ਸਕਦੀ।"
          },
