        "pa": "ਸਮਝਾਓ ਕਿ ਵਾਰ ਵਾਰ ਆਉਂਦਾ “ਕਈ ਕੋਟਿ” ਕਰਤਾਰ ਨੂੰ ਗਿਣ ਲੈਣ ਦੀ ਥਾਂ ਨਿਮਰਤਾ ਵੱਲ ਕਿਵੇਂ ਲੈ ਜਾਂਦਾ ਹੈ। ਫਿਰ ਵਿਸ਼ਾਲ ਪਸਾਰੇ ਨੂੰ ਅਖੀਰਲੀ ਪਉੜੀ ਦੀ ਸੁਆਸ ਸੁਆਸ ਸੰਭਾਲ ਨਾਲ ਜੋੜੋ।"
