            "pa": "ਜੇ ਤੁਹਾਡਾ ਪ੍ਰਭਾਵ ਜਾਂ ਧਨ ਬਦਲ ਜਾਵੇ, ਤਾਂ ਆਪਣੀ ਕਰਨੀ ਵਿੱਚ ਕਿਹੜਾ ਗੁਣ ਕਾਇਮ ਰੱਖਣਾ ਚਾਹੋਗੇ?"
