          "title": {
            "en": "The One within every capacity",
            "pa": "ਹਰ ਸਮਰੱਥਾ ਦੇ ਅੰਦਰ ਇੱਕ ਪ੍ਰਭੂ"
          },
          "explanation": {
            "en": "The pauri returns to the source of action. Human powers are dependent, while the Creator acts, causes action and unfolds creation in Divine delight. Nearness and transcendence are held together: the One is with all and beyond all. Understanding, seeing and discernment also belong within this Divine agency. The statement “the One and the many” connects unity with the variety of forms. The closing lines affirm freedom from death, destruction, coming and going. For the final expression, this draft follows Sahib Singh’s reading of the Divine abiding eternally in its own being. The movement encourages humility before a reality that supports all our capacities.",
            "pa": "ਪਉੜੀ ਫਿਰ ਕਰਨੀ ਦੇ ਮੂਲ ਵੱਲ ਆਉਂਦੀ ਹੈ। ਮਨੁੱਖ ਦੀਆਂ ਸਮਰੱਥਾਵਾਂ ਆਸਰੇ ਵਾਲੀਆਂ ਹਨ, ਜਦਕਿ ਕਰਤਾਰ ਆਪ ਕਰਦਾ, ਕਰਾਉਂਦਾ ਅਤੇ ਆਪਣੀ ਮੌਜ ਵਿੱਚ ਰਚਨਾ ਪਸਾਰਦਾ ਹੈ। ਨੇੜਤਾ ਅਤੇ ਪਰੇ ਹੋਣਾ ਇਕੱਠੇ ਹਨ: ਇੱਕ ਸਭ ਦੇ ਸੰਗ ਹੈ ਅਤੇ ਸਭ ਤੋਂ ਪਰੇ ਵੀ। ਸਮਝਣਾ, ਵੇਖਣਾ ਅਤੇ ਪਰਖਣਾ ਵੀ ਇਸੇ ਰੱਬੀ ਸਮਰੱਥਾ ਅੰਦਰ ਹਨ। ਆਪ ਇੱਕ ਅਤੇ ਆਪ ਅਨੇਕ ਹੋਣ ਦੀ ਗੱਲ ਏਕਤਾ ਨੂੰ ਰੂਪਾਂ ਦੀ ਵਿਭਿੰਨਤਾ ਨਾਲ ਜੋੜਦੀ ਹੈ। ਅਖੀਰ ਦੀਆਂ ਪੰਕਤੀਆਂ ਮੌਤ, ਨਾਸ ਅਤੇ ਆਉਣ ਜਾਣ ਤੋਂ ਪਰੇ ਅਵਸਥਾ ਦੱਸਦੀਆਂ ਹਨ। ਅੰਤਲੇ ਸ਼ਬਦਾਂ ਲਈ ਇਹ ਖਰੜਾ ਸਾਹਿਬ ਸਿੰਘ ਦੀ ਆਪਣੇ ਆਪ ਵਿੱਚ ਸਦਾ ਟਿਕੇ ਪ੍ਰਭੂ ਵਾਲੀ ਪੜ੍ਹਤ ਲੈਂਦਾ ਹੈ। ਸਾਡੀਆਂ ਸਾਰੀਆਂ ਸਮਰੱਥਾਵਾਂ ਦੇ ਆਧਾਰ ਅੱਗੇ ਨਿਮਰਤਾ ਦਾ ਸੱਦਾ ਹੈ।"
          },
