          "title": {
            "en": "Praise ripens into loving remembrance",
            "pa": "ਉਸਤਤਿ ਤੋਂ ਪ੍ਰੇਮ ਭਰੀ ਯਾਦ ਵੱਲ"
          },
          "explanation": {
            "en": "The closing pauri repeats words of affirmation: true, good, beautiful, pure and holy. It moves from the enduring Creator to what the Creator has made, then to Divine form and utterance, and finally to the person who remembers Naam with love. Recognition comes through the Guru’s grace. Sahib Singh explains the creation’s truth here as completeness, so the line need not mean that each individual object lasts forever. The speech heard and voiced through beings expresses the Divine presence running through the passage. After the examination of pride, the Ashtpadi ends in praise and a heart turned toward Naam.",
            "pa": "ਅਖੀਰਲੀ ਪਉੜੀ ਸੱਚ, ਭਲਾਈ, ਸੁੰਦਰਤਾ, ਨਿਰਮਲਤਾ ਅਤੇ ਪਵਿੱਤਰਤਾ ਦੇ ਸ਼ਬਦ ਦੁਹਰਾਉਂਦੀ ਹੈ। ਗੱਲ ਸਦਾ ਕਾਇਮ ਕਰਤਾਰ ਤੋਂ ਉਸ ਦੀ ਰਚਨਾ, ਫਿਰ ਉਸ ਦੇ ਰੂਪ ਅਤੇ ਬਾਣੀ ਅਤੇ ਅੰਤ ਵਿੱਚ ਪ੍ਰੇਮ ਨਾਲ ਨਾਮ ਜਪਣ ਵਾਲੇ ਜੀਵ ਤਕ ਜਾਂਦੀ ਹੈ। ਪਛਾਣ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਹੁੰਦੀ ਹੈ। ਸਾਹਿਬ ਸਿੰਘ ਇਥੇ ਰਚਨਾ ਦੇ ਸੱਚ ਨੂੰ ਮੁਕੰਮਲਤਾ ਨਾਲ ਸਮਝਾਉਂਦੇ ਹਨ; ਇਸ ਲਈ ਹਰ ਵੱਖਰੀ ਵਸਤੂ ਸਦਾ ਰਹਿਣ ਦਾ ਭਾਵ ਲੈਣਾ ਲਾਜ਼ਮੀ ਨਹੀਂ। ਜੀਵਾਂ ਰਾਹੀਂ ਸੁਣੀ ਅਤੇ ਉਚਾਰੀ ਜਾਂਦੀ ਬੋਲੀ ਇਸ ਪਉੜੀ ਦੀ ਰੱਬੀ ਹਾਜ਼ਰੀ ਨੂੰ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ। ਹੰਕਾਰ ਦੀ ਪੜਤਾਲ ਮਗਰੋਂ ਅਸਟਪਦੀ ਉਸਤਤਿ ਕਰਦੇ ਅਤੇ ਨਾਮ ਵੱਲ ਮੁੜੇ ਹਿਰਦੇ ਨਾਲ ਮੁੱਕਦੀ ਹੈ।"
          },
