      "teachBack": {
        "en": "Trace the movement from pride in the first pauri to contentment in the fifth and praise in the eighth. How do grace and Naam connect those movements? Explain why the humble person can be active and responsible while letting go of the claim to independent mastery.",
        "pa": "ਪਹਿਲੀ ਪਉੜੀ ਦੇ ਹੰਕਾਰ ਤੋਂ ਪੰਜਵੀਂ ਦੇ ਸੰਤੋਖ ਅਤੇ ਅੱਠਵੀਂ ਦੀ ਉਸਤਤਿ ਤਕ ਦੀ ਚਾਲ ਦੱਸੋ। ਮਿਹਰ ਅਤੇ ਨਾਮ ਇਨ੍ਹਾਂ ਨੂੰ ਕਿਵੇਂ ਜੋੜਦੇ ਹਨ? ਸਮਝਾਓ ਕਿ ਨਿਮਰ ਜੀਵ ਆਪਣੇ ਆਪ ਨੂੰ ਸੁਤੰਤਰ ਮਾਲਕ ਮੰਨਣ ਦਾ ਦਾਅਵਾ ਛੱਡ ਕੇ ਵੀ ਕਰਮਸ਼ੀਲ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰ ਕਿਵੇਂ ਰਹਿ ਸਕਦਾ ਹੈ।"
      },
      "caution": {
        "en": "Pauri 1 uses severe images alongside language of birth and death. Read them as the passage’s warning about pride and moral degradation; they do not authorize demeaning another person. The final pauri affirms the Creator and creation. Its language of truth and completeness does not require treating each changing object as everlasting. The reflections here are present-day educational applications, distinct from the original bani.",
        "pa": "ਪਹਿਲੀ ਪਉੜੀ ਵਿੱਚ ਜਨਮ ਮਰਨ ਦੀ ਬੋਲੀ ਨਾਲ ਤਿੱਖੀਆਂ ਮਿਸਾਲਾਂ ਆਉਂਦੀਆਂ ਹਨ। ਇਨ੍ਹਾਂ ਨੂੰ ਹੰਕਾਰ ਅਤੇ ਕਰਨੀ ਦੇ ਪਤਨ ਬਾਰੇ ਚੇਤਾਵਨੀ ਵਜੋਂ ਪੜ੍ਹੋ; ਇਨ੍ਹਾਂ ਨਾਲ ਕਿਸੇ ਹੋਰ ਮਨੁੱਖ ਨੂੰ ਹੇਠਾਂ ਦਿਖਾਉਣ ਦਾ ਹੱਕ ਨਹੀਂ ਮਿਲਦਾ। ਅਖੀਰਲੀ ਪਉੜੀ ਕਰਤਾਰ ਅਤੇ ਉਸ ਦੀ ਰਚਨਾ ਦੀ ਪ੍ਰਵਾਨਗੀ ਕਰਦੀ ਹੈ। ਸੱਚ ਅਤੇ ਮੁਕੰਮਲਤਾ ਦੀ ਇਹ ਬੋਲੀ ਹਰ ਬਦਲਦੀ ਵਸਤੂ ਨੂੰ ਸਦੀਵੀ ਮੰਨਣ ਦੀ ਮੰਗ ਨਹੀਂ ਕਰਦੀ। ਇਥੇ ਦਿੱਤੇ ਵਿਚਾਰ-ਸਵਾਲ ਅੱਜ ਦੇ ਜੀਵਨ ਲਈ ਸਿੱਖਿਆ ਦੇ ਅਮਲ ਹਨ ਅਤੇ ਮੂਲ ਬਾਣੀ ਤੋਂ ਵੱਖਰੇ ਹਨ।"
      },
